function capture(){if(!active||!doc?.body)return;const s=state(),scroll=doc.querySelector('.scroll');if(s.tab==='posts'&&scroll?.isConnected)s.offsets[key()]=scroll.scrollTop;const bridge=frame?.contentWindow?.RelaxeFeedStudy;if(s.tab==='posts'&&bridge&&original.length)s.saves[key()]=new Set(bridge.savedFixtures())}
function postFixtures(){if(viewMode==='history')return original.map((p,i)=>({...p,id:'history-'+context().account+'-'+p.id,age:['2h','3h','4h','2d','3d','1w','2w','3w','1mo','2mo'][i]}));const s=state(),guest=context().account==='guest',prefix=guest?'guest':s.source;const selected=guest?original.slice(4,8):s.source==='local'?original.slice(4,8):original.slice(0,7);return selected.map(p=>({...p,id:prefix+'-'+p.id}))}
function matches(item){return state().query.trim().toLowerCase().split(/\s+/).filter(Boolean).every(term=>{const sub=(item.sub||'').replace(/^r\//,'').toLowerCase();return term.startsWith('/r/')?sub===term.slice(3):[item.title,item.body,item.sub,item.author].join(' ').toLowerCase().includes(term)})}
